-- Egypt deep-dive ES/DE/FR translations (completing 209). INSERT OR IGNORE.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'es', 'Compensación centralizada — plataforma de la ETA (facturas y recibos electrónicos)', 'Esta página de análisis refleja la orientación técnica disponible públicamente a agosto de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. La ETA ajusta los alcances de las olas, los umbrales y la práctica sancionadora mediante decisiones y circulares — confirme los requisitos actuales directamente con la Autoridad Tributaria Egipcia o con su proveedor de integración antes de construir sobre ellos.', 'El despliegue de Egipto avanzó por dos vías paralelas bajo una misma autoridad: la facturación electrónica B2B/B2G validada por la ETA, introducida por fases desde noviembre de 2020 y universal desde abril de 2023, y un sistema independiente de recibos electrónicos B2C desplegado en olas escalonadas — con 2026 marcando el paso de la incorporación a la aplicación.', 'Egipto utiliza sus propios formatos estructurados definidos por la ETA en lugar de un estándar de tipo europeo: documentos JSON o XML, firmados digitalmente, con códigos de producto estandarizados y validados por la plataforma central, que asigna a cada documento su UUID oficial.', 'Todo pasa por la plataforma central de la ETA: las facturas se validan en tiempo real o casi real mediante integración por API, el portal web o la aplicación móvil, mientras que los recibos de consumidores fluyen desde los sistemas POS integrados con el sistema paralelo de recibos electrónicos.', 'Cumplir implica registrarse ante la ETA, obtener un certificado digital, mapear sus códigos de producto e integrar cada canal de venta — prestando atención por separado a la vía de facturas y a la de recibos.', 'Egipto respalda el mandato con consecuencias reales: multas explícitas por presentación tardía y por no registrarse desde 2026, denegación de créditos de IVA soportado sobre documentos no validados y una aplicación basada en consecuencias que alcanza los derechos de importación/exportación y los contratos públicos.', 'La facturación electrónica de Egipto, validada por la ETA, es obligatoria para todas las empresas registradas a efectos de IVA desde abril de 2023, las facturas en papel perdieron validez para la deducción del IVA en julio de 2023 y existe un despliegue paralelo de recibos electrónicos B2C. Desde enero de 2026 el régimen está en su etapa de aplicación: sanciones por presentación tardía, códigos QR en los recibos impresos y un umbral de registro reducido a 250.000 EGP.', '🏛️' FROM countries WHERE name_en = 'Egypt';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'de', 'Zentralisiertes Clearance-Modell — ETA-Plattform (E-Rechnungen + E-Belege)', 'Diese Länderanalyse spiegelt öffentlich verfügbare technische Hinweise mit Stand August 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. Die ETA passt Wellen-Anwendungsbereiche, Schwellenwerte und Sanktionspraxis per Beschluss und Rundschreiben an — bestätigen Sie aktuelle Anforderungen direkt bei der ägyptischen Steuerbehörde oder Ihrem Integrationsanbieter, bevor Sie dagegen entwickeln.', 'Ägyptens Rollout lief als zwei parallele Stränge unter einer Behörde: die ETA-geprüfte B2B/B2G-E-Rechnung, stufenweise ab November 2020 eingeführt und seit April 2023 universell, und ein separates B2C-E-Beleg-System in gestaffelten Wellen — wobei 2026 den Übergang vom Onboarding zur Durchsetzung markiert.', 'Ägypten nutzt eigene, von der ETA definierte strukturierte Formate statt eines Standards nach EU-Muster: JSON- oder XML-Dokumente, digital signiert, mit standardisierten Produktcodes, geprüft von der zentralen Plattform, die jedem Dokument seine offizielle UUID zuweist.', 'Alles läuft über die zentrale ETA-Plattform: Rechnungen werden in Echtzeit oder nahezu Echtzeit per API-Integration, Webportal oder Mobil-App geprüft, während Verbraucherbelege aus den an das parallele E-Beleg-System angebundenen Kassensystemen fließen.', 'Compliance bedeutet: Registrierung bei der ETA, Beschaffung eines digitalen Zertifikats, Zuordnung Ihrer Produktcodes und Anbindung jedes Vertriebskanals — wobei Rechnungs- und Belegstrang getrennte Aufmerksamkeit brauchen.', 'Ägypten setzt die Pflicht mit echten Konsequenzen durch: explizite Strafen für verspätete Übermittlung und versäumte Registrierung seit 2026, Versagung des Vorsteuerabzugs für ungeprüfte Dokumente und eine folgenbasierte Durchsetzung bis hin zu Import-/Exportrechten und öffentlichen Aufträgen.', 'Ägyptens ETA-geprüfte E-Rechnung ist seit April 2023 für alle umsatzsteuerregistrierten Unternehmen verpflichtend, Papierrechnungen verloren im Juli 2023 ihre Gültigkeit für den Vorsteuerabzug, und parallel läuft ein B2C-E-Beleg-Rollout. Seit Januar 2026 befindet sich das Regime in der Durchsetzungsphase: Strafen für verspätete Übermittlung, QR-Codes auf gedruckten Belegen und eine auf 250.000 EGP gesenkte Registrierungsschwelle.', '🏛️' FROM countries WHERE name_en = 'Egypt';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr', 'Validation préalable centralisée — plateforme de l''ETA (factures et reçus électroniques)', 'Cette analyse par pays reflète les directives techniques publiquement disponibles à août 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. L''ETA ajuste les périmètres des vagues, les seuils et la pratique des sanctions par décisions et circulaires — confirmez les exigences actuelles directement auprès de l''autorité fiscale égyptienne ou de votre prestataire d''intégration avant de construire votre intégration.', 'Le déploiement de l''Égypte a suivi deux voies parallèles sous une même autorité : la facturation électronique B2B/B2G validée par l''ETA, introduite par phases à partir de novembre 2020 et universelle depuis avril 2023, et un système distinct de reçus électroniques B2C déployé par vagues échelonnées — 2026 marquant le passage de l''intégration à l''application.', 'L''Égypte utilise ses propres formats structurés définis par l''ETA plutôt qu''une norme de type européen : des documents JSON ou XML, signés numériquement, portant des codes produits standardisés et validés par la plateforme centrale, qui attribue à chaque document son UUID officiel.', 'Tout transite par la plateforme centrale de l''ETA : les factures sont validées en temps réel ou quasi réel via l''intégration API, le portail web ou l''application mobile, tandis que les reçus des consommateurs proviennent des systèmes de caisse connectés au système parallèle de reçus électroniques.', 'Se mettre en conformité signifie s''enregistrer auprès de l''ETA, obtenir un certificat numérique, mapper ses codes produits et connecter chaque canal de vente — les volets factures et reçus exigeant une attention distincte.', 'L''Égypte assortit l''obligation de conséquences réelles : des amendes explicites pour transmission tardive et défaut d''enregistrement depuis 2026, le refus des crédits de TVA d''amont sur les documents non validés, et une application par conséquences touchant jusqu''aux droits d''import/export et aux marchés publics.', 'La facturation électronique égyptienne validée par l''ETA est obligatoire pour toutes les entreprises assujetties à la TVA depuis avril 2023, les factures papier ont perdu leur validité pour la déduction de la TVA en juillet 2023, et un déploiement parallèle de reçus électroniques B2C est en cours. Depuis janvier 2026, le régime est dans sa phase d''application : pénalités pour transmission tardive, codes QR sur les reçus imprimés et seuil d''enregistrement abaissé à 250 000 EGP.', '🏛️' FROM countries WHERE name_en = 'Egypt';

