INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Formato y estándar', '[["Formatos de documento", "JSON o XML según el esquema publicado por la ETA"], ["Firma", "Firma digital obligatoria (certificado HSM o token USB)"], ["Codificación de productos", "Códigos internacionales GS1 o codificación interna EGS (egipcia)"], ["Artefacto de validación", "La ETA asigna a cada documento validado un UUID oficial"]]', 'Egipto es anterior y ajeno al mundo de la EN 16931 — la ETA define su propio esquema documental, por lo que el trabajo con formatos europeos no se traslada directamente, y el mapeo de códigos de producto suele ser la mayor tarea puntual de integración.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Egypt' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Format & Standard', '[["Dokumentformate", "JSON oder XML nach dem veröffentlichten ETA-Schema"], ["Signatur", "Digitale Signatur erforderlich (HSM- oder USB-Token-Zertifikat)"], ["Produktcodierung", "Internationale GS1-Codes oder interne EGS-Codierung (ägyptisch)"], ["Clearance-Artefakt", "Die ETA weist jedem geprüften Dokument eine offizielle UUID zu"]]', 'Ägypten liegt vor und außerhalb der EN-16931-Welt — die ETA definiert ihr eigenes Dokumentschema, sodass europäische Formatarbeit nicht direkt übertragbar ist und das Produktcode-Mapping meist die größte einmalige Integrationsaufgabe darstellt.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Egypt' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Format et norme', '[["Formats de document", "JSON ou XML selon le schéma publié par l''ETA"], ["Signature", "Signature numérique requise (certificat HSM ou clé USB)"], ["Codage produits", "Codes internationaux GS1 ou codage interne EGS (égyptien)"], ["Artefact de validation", "L''ETA attribue à chaque document validé un UUID officiel"]]', 'L''Égypte précède et se situe hors du monde de l''EN 16931 — l''ETA définit son propre schéma documentaire, si bien que le travail sur les formats européens ne se transpose pas directement, et le mapping des codes produits est généralement la plus grosse tâche d''intégration ponctuelle.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Egypt' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Identificadores y registro', '[["Identidad del contribuyente", "Número de registro fiscal egipcio"], ["Certificado", "Certificado digital emitido por la ETA para la firma"], ["Registro", "A través del portal de facturación electrónica de la ETA (invoicing.eta.gov.eg)"], ["Dispositivos POS", "Cada dispositivo se registra con un número de serie en el sistema de recibos electrónicos"]]', 'El registro es por entidad, pero la integración es por canal: una entidad que vende B2B y B2C necesita tanto su integración de facturación como la inscripción de cada dispositivo POS en el sistema de recibos.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Egypt' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Kennungen & Registrierung', '[["Steuerpflichtigen-Identität", "Ägyptische Steuerregistrierungsnummer"], ["Zertifikat", "Von der ETA ausgestelltes digitales Signaturzertifikat"], ["Registrierung", "Über das E-Rechnungs-Portal der ETA (invoicing.eta.gov.eg)"], ["Kassengeräte", "Jedes Gerät wird mit einer Seriennummer im E-Beleg-System registriert"]]', 'Die Registrierung erfolgt je Gesellschaft, die Integration je Kanal: Eine Gesellschaft mit B2B- und B2C-Geschäft braucht sowohl ihre Rechnungsintegration als auch die Anmeldung jedes Kassengeräts im Belegsystem.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Egypt' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Identifiants et enregistrement', '[["Identité du contribuable", "Numéro d''enregistrement fiscal égyptien"], ["Certificat", "Certificat numérique délivré par l''ETA pour la signature"], ["Enregistrement", "Via le portail de facturation électronique de l''ETA (invoicing.eta.gov.eg)"], ["Terminaux POS", "Chaque terminal est enregistré avec un numéro de série dans le système de reçus électroniques"]]', 'L''enregistrement se fait par entité, mais l''intégration par canal : une entité vendant en B2B et en B2C a besoin à la fois de son intégration de facturation et de l''enrôlement de chaque terminal POS dans le système de reçus.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Egypt' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Contenido obligatorio', '[["Datos de las partes", "Números de registro fiscal del vendedor y del comprador"], ["Nivel de línea", "Códigos de producto estandarizados, cantidades, importes"], ["Al validarse", "UUID de la ETA incorporado en el documento validado"], ["Recibos impresos", "Código QR que enlaza con el registro validado de la ETA (desde 2026)"]]', 'El contenido faltante se trata como incumplimiento, no como formalidad — una factura sin el número fiscal del comprador o sin la codificación exigida puede rechazarse o sancionarse, y desde 2026 un recibo impreso sin su código QR constituye en sí mismo una infracción.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Egypt' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Pflichtinhalte', '[["Parteidaten", "Steuerregistrierungsnummern von Verkäufer und Käufer"], ["Positionsebene", "Standardisierte Produktcodes, Mengen, Beträge"], ["Bei Clearance", "In das validierte Dokument eingebettete ETA-UUID"], ["Gedruckte E-Belege", "QR-Code mit Verweis auf den validierten ETA-Datensatz (ab 2026)"]]', 'Fehlende Inhalte gelten als Verstoß, nicht als Formsache — eine Rechnung ohne die Steuernummer des Käufers oder die geforderte Codierung kann abgelehnt oder sanktioniert werden, und ab 2026 ist ein gedruckter Beleg ohne QR-Code selbst ein Verstoß.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Egypt' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Contenu obligatoire', '[["Données des parties", "Numéros d''enregistrement fiscal du vendeur et de l''acheteur"], ["Niveau ligne", "Codes produits standardisés, quantités, montants"], ["À la validation", "UUID de l''ETA intégré dans le document validé"], ["Reçus imprimés", "Code QR renvoyant à l''enregistrement validé de l''ETA (à partir de 2026)"]]', 'Un contenu manquant est traité comme un manquement, pas comme une formalité — une facture sans le numéro fiscal de l''acheteur ou sans le codage requis peut être rejetée ou sanctionnée, et depuis 2026 un reçu imprimé sans son code QR constitue en soi une infraction.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Egypt' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Archivo', '[["Período de conservación", "5 años según los procedimientos tributarios egipcios"], ["Qué conservar", "El documento validado (con su UUID de la ETA) más los registros de envío"]]', 'El registro validado en la plataforma de la ETA es el que da fe — mantenga su propio archivo conciliado con él, ya que las disputas se resuelven con lo que consta en la plataforma.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Egypt' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Archivierung', '[["Aufbewahrungsfrist", "5 Jahre nach ägyptischem Steuerverfahrensrecht"], ["Aufzubewahren", "Das geprüfte Dokument (mit seiner ETA-UUID) plus Übermittlungsnachweise"]]', 'Der geprüfte Datensatz in der ETA-Plattform ist der maßgebliche — halten Sie Ihr eigenes Archiv damit abgeglichen, denn Streitfälle werden nach dem entschieden, was die Plattform enthält.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Egypt' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Archivage', '[["Durée de conservation", "5 ans selon les procédures fiscales égyptiennes"], ["À conserver", "Le document validé (avec son UUID ETA) plus les enregistrements de transmission"]]', 'L''enregistrement validé dans la plateforme de l''ETA fait foi — gardez vos propres archives rapprochées de celle-ci, car les litiges se règlent sur la base de ce que détient la plateforme.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Egypt' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Modelo de red', '[["Modelo", "Compensación centralizada a través de la plataforma de la ETA"], ["Vías", "Facturación electrónica (B2B/B2G) y un sistema independiente de recibos electrónicos (B2C)"], ["Plazos", "Envío en tiempo real o casi real; los períodos de gracia heredados se están eliminando"], ["Base legal", "Ley N.º 206 de 2020 (Ley de Procedimientos Tributarios Unificados)"]]', 'Las dos vías son operativamente independientes — cumplir plenamente en facturación no dice nada sobre su parque de POS, y viceversa. Trátelas como dos integraciones bajo una misma autoridad.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Egypt' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Netzwerkmodell', '[["Modell", "Zentralisiertes Clearance über die ETA-Plattform"], ["Stränge", "E-Rechnung (B2B/B2G) und ein separates E-Beleg-System (B2C)"], ["Timing", "Übermittlung in Echtzeit oder nahezu Echtzeit; alte Karenzfenster laufen aus"], ["Rechtsgrundlage", "Gesetz Nr. 206 von 2020 (Gesetz über einheitliche Steuerverfahren)"]]', 'Die beiden Stränge sind operativ getrennt — volle Compliance bei der Rechnungsstellung sagt nichts über Ihre Kasseninfrastruktur aus und umgekehrt. Behandeln Sie sie als zwei Integrationen unter einer Behörde.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Egypt' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Modèle de réseau', '[["Modèle", "Validation préalable centralisée via la plateforme de l''ETA"], ["Volets", "Facturation électronique (B2B/B2G) et système distinct de reçus électroniques (B2C)"], ["Délais", "Transmission en temps réel ou quasi réel ; les fenêtres de grâce héritées disparaissent"], ["Base légale", "Loi n° 206 de 2020 (loi sur les procédures fiscales unifiées)"]]', 'Les deux volets sont opérationnellement distincts — être pleinement conforme sur la facturation ne dit rien de votre parc de caisses, et inversement. Traitez-les comme deux intégrations sous une même autorité.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Egypt' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Canales', '[["Integración ERP", "SDK / API de la ETA para el envío directo entre sistemas"], ["Portal web", "Emisión manual para volúmenes bajos"], ["Aplicación móvil", "App gratuita de la ETA dirigida a pequeños contribuyentes"], ["POS", "Integración del punto de venta o del ERP con el sistema de recibos electrónicos para B2C"]]', 'El portal gratuito y la app móvil existen para que la reducción del umbral a 250.000 EGP no deje sin opciones a las pequeñas empresas sin software — pero cualquier operación con volumen real necesita la vía de las API.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Egypt' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Kanäle', '[["ERP-Integration", "ETA-SDK / APIs für direkte System-zu-System-Übermittlung"], ["Webportal", "Manuelle Ausstellung für geringe Volumina"], ["Mobil-App", "Kostenlose ETA-App für kleine Steuerpflichtige"], ["POS", "Kassen- oder ERP-Anbindung an das E-Beleg-System für B2C"]]', 'Das kostenlose Portal und die Mobil-App existieren, damit die Schwellensenkung auf 250.000 EGP Kleinunternehmen ohne Software nicht stranden lässt — alles mit echtem Volumen braucht jedoch den API-Weg.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Egypt' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Canaux', '[["Intégration ERP", "SDK / API de l''ETA pour la transmission directe de système à système"], ["Portail web", "Émission manuelle pour les faibles volumes"], ["Application mobile", "Application gratuite de l''ETA destinée aux petits contribuables"], ["POS", "Intégration du point de vente ou de l''ERP au système de reçus électroniques pour le B2C"]]', 'Le portail gratuit et l''application mobile existent pour que l''abaissement du seuil à 250 000 EGP ne laisse pas les petites entreprises sans solution — mais toute activité à volume réel passe par la voie des API.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Egypt' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'El giro de 2026: de la incorporación a la aplicación', '[["Umbral de registro", "Reducido de 500.000 a 250.000 EGP de ingresos brutos anuales"], ["Plazo de registro", "31 de marzo de 2026 (vencido — las sanciones diarias se acumulan para los no registrados)"], ["Ampliación de recibos electrónicos", "Octava subfase vigente desde el 15 de septiembre de 2025 (Decisión 281/2025)"]]', 'La postura de la ETA cambió en enero de 2026: de hacer crecer el sistema a vigilarlo — si alguna entidad egipcia de su grupo confiaba en pasar desapercibida por su tamaño, esa suposición ahora sale cara.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Egypt' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Die Wende 2026: vom Onboarding zur Durchsetzung', '[["Registrierungsschwelle", "Von 500.000 auf 250.000 EGP Bruttojahresumsatz gesenkt"], ["Registrierungsfrist", "31. März 2026 (abgelaufen — für Nichtregistrierte laufen Tagesstrafen auf)"], ["E-Beleg-Ausweitung", "Achte Teilphase in Kraft seit 15. September 2025 (Beschluss 281/2025)"]]', 'Die Haltung der ETA änderte sich im Januar 2026 vom Ausbau des Systems zu dessen Überwachung — falls eine ägyptische Gesellschaft Ihrer Gruppe darauf gebaut hat, klein und unbemerkt zu bleiben, wird diese Annahme jetzt teuer.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Egypt' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Le tournant de 2026 : de l''intégration à l''application', '[["Seuil d''enregistrement", "Abaissé de 500 000 à 250 000 EGP de chiffre d''affaires brut annuel"], ["Date limite d''enregistrement", "31 mars 2026 (expirée — les pénalités quotidiennes s''accumulent pour les non-enregistrés)"], ["Extension des reçus électroniques", "Huitième sous-phase en vigueur depuis le 15 septembre 2025 (décision 281/2025)"]]', 'La posture de l''ETA a changé en janvier 2026 : de la croissance du système à sa surveillance — si une entité égyptienne de votre groupe comptait sur sa petite taille pour passer inaperçue, cette hypothèse coûte désormais cher.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Egypt' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '⚖️ Multas con contador diario', NULL, NULL, 'Incumplir el plazo de registro conlleva una multa de 20.000 EGP más 1.000 EGP por día hasta su resolución, y desde enero de 2026 un régimen sancionador explícito se aplica a la presentación tardía de facturas y recibos electrónicos. En el extremo más grave — documentos no conformes o fraudulentos — las multas alcanzan los 50.000 EGP con posible pena de prisión.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Egypt' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '⚖️ Strafen mit Tageszähler', NULL, NULL, 'Wer die Registrierungsfrist versäumt, zahlt 20.000 EGP zuzüglich 1.000 EGP pro Tag bis zur Behebung, und seit Januar 2026 gilt ein explizites Sanktionsregime für die verspätete Übermittlung von E-Rechnungen und E-Belegen. Am schweren Ende — nicht konforme oder betrügerische Dokumente — erreichen die Strafen 50.000 EGP mit möglicher Haftstrafe.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Egypt' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '⚖️ Amendes avec compteur quotidien', NULL, NULL, 'Manquer la date limite d''enregistrement entraîne une amende de 20 000 EGP plus 1 000 EGP par jour jusqu''à régularisation, et depuis janvier 2026 un régime de pénalités explicite s''applique à la transmission tardive des factures et reçus électroniques. Au niveau le plus grave — documents non conformes ou frauduleux — les amendes atteignent 50 000 EGP avec peine d''emprisonnement possible.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Egypt' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🧾 Consecuencias en el IVA', NULL, NULL, 'Las facturas en papel no permiten deducir el IVA desde julio de 2023 — solo las facturas electrónicas validadas por la ETA permiten recuperar el IVA soportado. Un proveedor fuera del sistema no solo se arriesga a multas: sus facturas carecen de valor para sus clientes empresariales, y ese es el verdadero motor de aplicación del mandato.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Egypt' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🧾 Umsatzsteuerliche Folgen', NULL, NULL, 'Papierrechnungen berechtigen seit Juli 2023 nicht mehr zum Vorsteuerabzug — nur ETA-geprüfte elektronische Rechnungen erlauben die Vorsteuererstattung. Ein Lieferant außerhalb des Systems riskiert nicht nur Strafen: Seine Rechnungen sind für seine Geschäftskunden wertlos, und genau das ist der eigentliche Durchsetzungsmotor der Pflicht.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Egypt' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🧾 Conséquences sur la TVA', NULL, NULL, 'Les factures papier ne permettent plus de déduire la TVA depuis juillet 2023 — seules les factures électroniques validées par l''ETA permettent de récupérer la TVA d''amont. Un fournisseur hors du système ne risque pas seulement des amendes : ses factures n''ont aucune valeur pour ses clients professionnels, et c''est là le véritable moteur d''application de l''obligation.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Egypt' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🚫 Aplicación basada en consecuencias', NULL, NULL, 'Más allá de las multas, el marco de aplicación escalonado puede suspender la capacidad de una empresa para emitir facturas válidas, y el incumplimiento puede suponer la exclusión de contratos públicos y restricciones a la importación/exportación — la ETA cruza automáticamente las declaraciones de IVA con las solicitudes de exención.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Egypt' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🚫 Folgenbasierte Durchsetzung', NULL, NULL, 'Über Geldstrafen hinaus kann das gestufte Durchsetzungssystem einem Unternehmen die Fähigkeit entziehen, gültige Rechnungen auszustellen, und Verstöße können den Ausschluss von öffentlichen Aufträgen sowie Import-/Exportbeschränkungen bedeuten — die ETA gleicht Umsatzsteuererklärungen automatisch mit Befreiungsanträgen ab.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Egypt' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🚫 Application par conséquences', NULL, NULL, 'Au-delà des amendes, le dispositif d''application à plusieurs niveaux peut suspendre la capacité d''une entreprise à émettre des factures valides, et le non-respect peut entraîner l''exclusion des marchés publics et des restrictions à l''import/export — l''ETA recoupe automatiquement les déclarations de TVA avec les demandes d''exemption.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Egypt' AND dc.section = 'penalties_related' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Confirme el alcance de cada entidad y canal', 'Utilice la consulta de la ETA con su número de registro fiscal — las vías de facturas y recibos tienen decisiones de ola separadas, así que compruebe ambas, y recuerde que el umbral se mide sobre ingresos brutos antes de gastos.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Egypt' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bestimmen Sie den Anwendungsbereich je Gesellschaft und Kanal', 'Nutzen Sie die ETA-Abfrage mit Ihrer Steuerregistrierungsnummer — Rechnungs- und Belegstrang haben separate Wellenbeschlüsse, prüfen Sie also beide, und denken Sie daran, dass die Schwelle am Bruttoumsatz vor Kosten gemessen wird.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Egypt' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Confirmez le périmètre de chaque entité et canal', 'Utilisez la consultation de l''ETA avec votre numéro d''enregistrement fiscal — les volets factures et reçus relèvent de décisions de vagues distinctes, vérifiez donc les deux, et rappelez-vous que le seuil se mesure sur le chiffre d''affaires brut avant charges.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Egypt' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Regístrese ante la ETA y obtenga su certificado', 'Regístrese en el portal de facturación electrónica y obtenga el certificado digital utilizado para firmar los documentos; sin él, nada de lo que envíe será válido.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Egypt' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Registrieren Sie sich bei der ETA und beschaffen Sie Ihr Zertifikat', 'Registrieren Sie sich im E-Rechnungs-Portal und beschaffen Sie das digitale Zertifikat zum Signieren der Dokumente; ohne dieses ist nichts, was Sie übermitteln, gültig.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Egypt' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Enregistrez-vous auprès de l''ETA et obtenez votre certificat', 'Enregistrez-vous sur le portail de facturation électronique et obtenez le certificat numérique servant à signer les documents ; sans lui, rien de ce que vous transmettez n''est valide.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Egypt' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Mapee su catálogo de productos a códigos GS1 o EGS', 'Suele ser la mayor tarea puntual — cada línea necesita un código estandarizado, y los artículos sin codificar suponen riesgo de rechazo.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Egypt' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Ordnen Sie Ihren Produktkatalog GS1- oder EGS-Codes zu', 'Meist die größte einmalige Aufgabe — jede Position braucht einen standardisierten Code, und uncodierte Artikel bergen Ablehnungsrisiko.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Egypt' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Mappez votre catalogue produits aux codes GS1 ou EGS', 'C''est généralement la plus grosse tâche ponctuelle — chaque ligne nécessite un code standardisé, et les articles non codés présentent un risque de rejet.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Egypt' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Integre sus sistemas de emisión', 'Las entidades de gran volumen deben integrar sus ERP mediante el SDK/las API de la ETA; el portal web y la app móvil gratuita cubren los casos de bajo volumen y pequeños contribuyentes.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Egypt' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Integrieren Sie Ihre ausstellenden Systeme', 'Gesellschaften mit hohem Volumen sollten ihre ERP-Systeme über das ETA-SDK/die APIs anbinden; Webportal und kostenlose Mobil-App decken Fälle mit geringem Volumen und kleine Steuerpflichtige ab.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Egypt' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Intégrez vos systèmes d''émission', 'Les entités à fort volume doivent intégrer leurs ERP via le SDK/les API de l''ETA ; le portail web et l''application mobile gratuite couvrent les faibles volumes et les petits contribuables.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Egypt' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Incorpore su parque de POS al sistema de recibos electrónicos', 'Registre cada dispositivo, intégrelo con la plataforma central para la verificación en tiempo real y asegúrese de que los recibos impresos llevan el código QR que enlaza con el registro validado.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Egypt' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bringen Sie Ihre Kasseninfrastruktur in das E-Beleg-System', 'Registrieren Sie jedes Gerät, binden Sie es für die Echtzeit-Verifizierung an die zentrale Plattform an und stellen Sie sicher, dass gedruckte Belege den QR-Code mit Verweis auf den validierten Datensatz tragen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Egypt' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Intégrez votre parc de caisses au système de reçus électroniques', 'Enregistrez chaque terminal, connectez-le à la plateforme centrale pour la vérification en temps réel et assurez-vous que les reçus imprimés portent le code QR renvoyant à l''enregistrement validé.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Egypt' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Audite la puntualidad y concilie con la plataforma', 'Desde enero de 2026, la presentación tardía conlleva sanciones explícitas — supervise los plazos de envío y concilie su archivo con los registros validados de la ETA de forma periódica.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Egypt' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Prüfen Sie die Pünktlichkeit und gleichen Sie mit der Plattform ab', 'Seit Januar 2026 zieht verspätete Übermittlung explizite Strafen nach sich — überwachen Sie Übermittlungsfristen und gleichen Sie Ihr Archiv regelmäßig mit den geprüften ETA-Datensätzen ab.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Egypt' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Auditez la ponctualité et rapprochez avec la plateforme', 'Depuis janvier 2026, la transmission tardive entraîne des pénalités explicites — surveillez les délais d''envoi et rapprochez régulièrement vos archives des enregistrements validés de l''ETA.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Egypt' AND ds.sort_order = 5;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'es', 'Portal de facturación electrónica de la ETA' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Egypt' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'de', 'E-Rechnungs-Portal der ETA' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Egypt' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'fr', 'Portail de facturation électronique de l''ETA' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Egypt' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'es', 'Autoridad Tributaria Egipcia' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Egypt' AND dp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'de', 'Ägyptische Steuerbehörde' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Egypt' AND dp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'fr', 'Autorité fiscale égyptienne' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Egypt' AND dp.sort_order = 1;
